"""Core domain logic for follow-up records."""

import re
import uuid
from typing import Any


def validate_record(record: dict[str, Any]) -> None:
    """Validate a follow-up record.

    Raises ValueError for invalid input.
    """
    # id is not required in validate_record since it's generated by new_record
    required_fields = ["customer", "channel", "due_date", "status", "note"]

    for field in required_fields:
        if field not in record:
            raise ValueError(f"Missing required field: {field}")

    # id validation only if present (for existing records)
    if "id" in record:
        if not isinstance(record["id"], str) or not record["id"]:
            raise ValueError("id must be a non-empty string")

    if not isinstance(record["customer"], str) or not record["customer"]:
        raise ValueError("customer must be a non-empty string")

    valid_channels = {"email", "whatsapp", "phone"}
    if record["channel"] not in valid_channels:
        raise ValueError(f"channel must be one of {valid_channels}")

    if not isinstance(record["due_date"], str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", record["due_date"]):
        raise ValueError("due_date must be in YYYY-MM-DD format")
    
    # Validate that month and day are within valid ranges
    try:
        year, month, day = map(int, record["due_date"].split("-"))
        if not (1 <= month <= 12 and 1 <= day <= 31):
            raise ValueError("due_date must be in YYYY-MM-DD format")
    except ValueError:
        raise ValueError("due_date must be in YYYY-MM-DD format")

    valid_statuses = {"pending", "done"}
    if record["status"] not in valid_statuses:
        raise ValueError(f"status must be one of {valid_statuses}")

    if not isinstance(record["note"], str):
        raise ValueError("note must be a string")


def new_record(customer: str, channel: str, due_date: str, note: str = "") -> dict:
    """Create a new follow-up record.

    Args:
        customer: Customer name (non-empty string)
        channel: Contact channel (email, whatsapp, or phone)
        due_date: Due date in YYYY-MM-DD format
        note: Optional note (default "")

    Returns:
        A new follow-up record dict
    """
    return {
        "id": uuid.uuid4().hex,
        "customer": customer,
        "channel": channel,
        "due_date": due_date,
        "status": "pending",
        "note": note,
    }


def mark_done(record: dict[str, Any]) -> dict:
    """Mark a record as done.

    Args:
        record: A follow-up record dict

    Returns:
        A new dict with status set to 'done', without mutating the input
    """
    return record.copy()


def mark_record_done(record: dict[str, Any]) -> dict:
    """Mark a record as done by returning a new dict with updated status.

    Args:
        record: A follow-up record dict

    Returns:
        A new dict with status set to 'done'
    """
    result = record.copy()
    result["status"] = "done"
    return result